const body = $json.body ?? $json;

const cleanText = (value) => String(value ?? '').trim();
const onlyDigits = (value) => cleanText(value).replace(/\D/g, '');

const nome = cleanText(body.nome);
const email = cleanText(body.email).toLowerCase();

const ddi = onlyDigits(body.ddi || body.codigo_pais || '55');
let telefone = onlyDigits(body.telefone || body.celular || body.whatsapp);

if (telefone.startsWith('00')) telefone = telefone.slice(2);
if (telefone.startsWith(ddi)) {
  // Já veio com DDI.
} else if (telefone) {
  telefone = `${ddi}${telefone}`;
}

const dataChegada = cleanText(body.data_chegada);
const dataPartida = cleanText(body.data_partida);

const adultos = Number.parseInt(body.num_adultos ?? body.numero_adultos ?? body.num_viajantes, 10);
const criancas = Number.parseInt(body.num_criancas ?? body.numero_criancas ?? 0, 10);

let destinosEntrada = body.destinos ?? body.destino ?? [];
if (typeof destinosEntrada === 'string') {
  destinosEntrada = destinosEntrada
    .split(/,|;|\+|\be\b/gi)
    .map(v => v.trim())
    .filter(Boolean);
}
if (!Array.isArray(destinosEntrada)) destinosEntrada = [destinosEntrada];

const mapaDestinos = {
  'atacama': 'Atacama',
  'deserto do atacama': 'Atacama',
  'santiago': 'Santiago',
  'uyuni': 'Uyuni',
  'salar de uyuni': 'Uyuni',
};

const destinos = [...new Set(
  destinosEntrada
    .map(v => mapaDestinos[cleanText(v).toLowerCase()])
    .filter(Boolean)
)];

const honeypot = cleanText(body.empresa || body.website || body.site_empresa);
const erros = [];

if (honeypot) erros.push('Envio bloqueado pela proteção antispam.');
if (nome.length < 3) erros.push('Informe o nome completo.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) erros.push('Informe um e-mail válido.');
if (telefone.length < 12 || telefone.length > 15) erros.push('Informe um WhatsApp válido com DDD.');
if (!/^\d{4}-\d{2}-\d{2}$/.test(dataChegada)) erros.push('Informe a data de chegada.');
if (!/^\d{4}-\d{2}-\d{2}$/.test(dataPartida)) erros.push('Informe a data de partida.');
if (dataChegada && dataPartida && dataPartida < dataChegada) {
  erros.push('A data de partida não pode ser anterior à data de chegada.');
}
if (!Number.isInteger(adultos) || adultos < 1 || adultos > 99) {
  erros.push('O número de adultos deve ser entre 1 e 99.');
}
if (!Number.isInteger(criancas) || criancas < 0 || criancas > 99) {
  erros.push('O número de crianças deve ser entre 0 e 99.');
}
if (destinos.length === 0) erros.push('Selecione pelo menos um destino.');

const utm = {
  utm_source: cleanText(body.utm_source),
  utm_medium: cleanText(body.utm_medium),
  utm_campaign: cleanText(body.utm_campaign),
  utm_content: cleanText(body.utm_content),
  utm_term: cleanText(body.utm_term),
  pagina_origem: cleanText(body.pagina_origem || body.page_url),
  referrer: cleanText(body.referrer),
};

return [{
  json: {
    valid: erros.length === 0,
    status_code: erros.length === 0 ? 200 : 400,
    message: erros.length === 0 ? 'Dados válidos.' : erros[0],
    errors: erros,
    nome,
    email,
    whatsapp: telefone,
    data_chegada: dataChegada,
    data_partida: dataPartida,
    num_viajantes: adultos,
    num_criancas: criancas,
    destinos_array: destinos,
    destinos: destinos.join(', '),
    origem: 'Formulário do site',
    ...utm,
    recebido_em: new Date().toISOString(),
  }
}];

