(() => {
  const novo = $('Validar e normalizar').first().json;
  const atual = $('Buscar lead pelo WhatsApp').first().json.body ?? {};

  const estaVazio = (valor) => {
    if (valor === null || valor === undefined) return true;

    if (typeof valor === 'string' && valor.trim() === '') {
      return true;
    }

    if (Array.isArray(valor) && valor.length === 0) {
      return true;
    }

    if (
      typeof valor === 'object' &&
      !Array.isArray(valor) &&
      Object.keys(valor).length === 0
    ) {
      return true;
    }

    return false;
  };

  const preservarOuPreencher = (campo, valorNovo) => {
    return estaVazio(atual[campo])
      ? valorNovo
      : atual[campo];
  };

  return {
    nome: preservarOuPreencher('nome', novo.nome),

    whatsapp: preservarOuPreencher(
      'whatsapp',
      novo.whatsapp
    ),

    destinos: preservarOuPreencher(
      'destinos',
      novo.destinos
    ),

    email: preservarOuPreencher(
      'email',
      novo.email
    ),

    num_viajantes: preservarOuPreencher(
      'num_viajantes',
      novo.num_viajantes
    ),

    num_criancas: preservarOuPreencher(
      'num_criancas',
      novo.num_criancas
    ),

    data_chegada: preservarOuPreencher(
      'data_chegada',
      novo.data_chegada
    ),

    data_partida: preservarOuPreencher(
      'data_partida',
      novo.data_partida
    ),

    datas_destinos: preservarOuPreencher(
      'datas_destinos',
      {}
    ),

    dias_por_destino: preservarOuPreencher(
      'dias_por_destino',
      {}
    )
  };
})()
}}

