const normalizado = $('Validar e normalizar').first().json;
const busca = $('Buscar lead pelo WhatsApp').first().json;

// Resposta recebida do nó "Criar novo lead"
// ou do nó "Atualizar lead existente"
const response = $json;
const statusCode = Number(response.statusCode ?? 200);
const body = response.body ?? response;

// Verifica se o lead já existia antes do processamento
const buscaStatusCode = Number(busca.statusCode ?? 0);

const leadExistia =
  buscaStatusCode === 200 &&
  Boolean(busca.body?.id);

// Obtém o ID retornado pela criação, atualização ou busca
const leadId =
  body?.id ??
  body?.lead_id ??
  busca.body?.id ??
  null;

// Considera sucesso apenas se o CRM respondeu com 2xx
// e foi possível identificar o lead
const ok =
  statusCode >= 200 &&
  statusCode < 300 &&
  Boolean(leadId);

// Monta as informações de campanha
const utmPartes = [
  normalizado.utm_source &&
    `utm_source=${normalizado.utm_source}`,

  normalizado.utm_medium &&
    `utm_medium=${normalizado.utm_medium}`,

  normalizado.utm_campaign &&
    `utm_campaign=${normalizado.utm_campaign}`,

  normalizado.utm_content &&
    `utm_content=${normalizado.utm_content}`,

  normalizado.utm_term &&
    `utm_term=${normalizado.utm_term}`,
].filter(Boolean);

// Monta a anotação que será adicionada ao lead
const anotacao = [
  'Novo envio recebido pelo formulário do site.',

  `Destinos: ${normalizado.destinos}.`,

  `Adultos: ${normalizado.num_viajantes}.`,

  `Crianças: ${normalizado.num_criancas}.`,

  `Chegada: ${normalizado.data_chegada}.`,

  `Partida: ${normalizado.data_partida}.`,

  normalizado.pagina_origem &&
    `Página: ${normalizado.pagina_origem}.`,

  utmPartes.length > 0 &&
    `Campanha: ${utmPartes.join(' | ')}.`,
]
  .filter(Boolean)
  .join(' ');

return [
  {
    json: {
      ok,
      status_code_crm: statusCode,
      lead_id: leadId,
      acao: leadExistia ? 'atualizado' : 'criado',
      anotacao,

      ...normalizado,

      crm_body: body,
    },
  },
];

const contexto = $('Preparar contexto do lead').first().json;
const funil = $('Adicionar ao funil Vendas Formulário').first().json;
const nota = $json;

const funilStatus = Number(funil.statusCode ?? 200);
const notaStatus = Number(nota.statusCode ?? 200);

// 409 significa que o lead já estava nesse funil; nesse caso, preservamos a etapa atual.
const funilOk = (funilStatus >= 200 && funilStatus < 300) || funilStatus === 409;
const notaOk = notaStatus >= 200 && notaStatus < 300;

return [{
  json: {
    sucesso: true,
    mensagem: 'Solicitação enviada com sucesso! Em breve entraremos em contato.',
    lead_id: contexto.lead_id,
    acao: contexto.acao,
    funil: 'Vendas: Formulário',
    etapa_inicial: funilStatus === 409 ? 'Etapa atual preservada' : 'Nova Oportunidade',
    funil_ok: funilOk,
    anotacao_ok: notaOk,
  }
}];
